import brandsLogo from '@/assets/img/logo/brands-logo.png';
import brandShape1 from '@/assets/img/shapes/brand-shape1.png';
import headingSpan from '@/assets/img/shapes/headding1-span.png';
import { Link } from 'gatsby';
import React, { useEffect, useRef } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import VanillaTilt from 'vanilla-tilt';

const Brands = () => {
  const tiltRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (tiltRef.current) {
      VanillaTilt.init(tiltRef.current, {
        max: 20,
        speed: 500,
        // glare: true,
        'max-glare': 0.2,
        scale: 1.05,
        perspective: 1000,
      });
    }
  }, []);

  return (
    <div className="brands _relative sp">
      <Container>
        <Row>
          <Col lg={6} className="m-auto text-center">
            <div className="headding1">
              <span className="span" data-aos="fade-up" data-aos-duration="800">
                <img src={headingSpan} alt="" /> Team Collaboration
              </span>
              <h2 data-aos="fade-up" data-aos-duration="1000">
                Connect entire <span className="after">workflows</span>
              </h2>
              <div className="space16"></div>
              <p data-aos="fade-up" data-aos-duration="900">
                Our intuitive platform is designed to streamline your workflow, offering a
                comprehensive suite of tools a simplify every aspect of project oversight.
              </p>
              <h6 data-aos="fade-up" data-aos-duration="1100">
                Explore Our{' '}
                <Link to="/features" className="after">
                  Integration Library
                </Link>
              </h6>
            </div>
          </Col>
        </Row>

        <Row>
          <Col lg={12}>
            <div
              ref={tiltRef}
              className="brands-image"
              data-tilt
              data-tilt-full-page-listening
              data-tilt-perspective="3000"
            >
              <img src={brandsLogo} alt="Brands Logo" />
            </div>
          </Col>
        </Row>
      </Container>

      <img className="brand-shape1 shape-animaiton2" src={brandShape1} alt="" />
      <img className="brand-shape2 shape-animaiton1" src={brandShape1} alt="" />
      <img className="brand-shape3" src={brandShape1} alt="" />
    </div>
  );
};

export default Brands;
